 311:         if let Ok(ip) = unbracketed.parse::<IpAddr>() {
 312:             (None, Some(normalize_ip(ip)))
 313:         } else {
 314:             match normalize_hostname(unbracketed) {
 315:                 Ok(h) => (Some(h), None),
 316:                 Err(_) => return Err(GateDenial::InvalidHost(locator.host.to_string())),
 317:             }
 318:         };
